const j = $input.first().json;
const actionType = j.action_type || 'get_price';
if (actionType !== 'get_price') {
  return [{ json: { logged: false, skip_reason: 'not_important_event' } }];
}
const status = j.status || (j.manual_quote || j.error ? 'failed' : 'success');
const output = j.output_summary
  || (j.final_price_usd != null ? `final_price_usd=${j.final_price_usd}` : null)
  || j.error
  || j.manual_quote_reason
  || j.reason
  || null;
return [{ json: {
  agent_name: 'sales',
  action_type: 'get_price',
  lead_id: j.lead_id || null,
  customer_id: j.customer_id || null,
  source_channel: j.source_channel || j.channel || null,
  input_summary: (j.input_summary || j.pricing_input || '').slice(0, 500) || null,
  output_summary: output ? String(output).slice(0, 500) : null,
  status: status === 'failed' || status === 'fail' ? 'failed' : 'success',
  metadata: j.metadata || { phase1: 'pricing_action' }
}}];
